package com.tehang.enterpriserisk.service;
import java.net.URI;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.time.Instant;import java.util.*;import javax.crypto.Cipher;import javax.crypto.spec.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
@Service public class WecomRobotService {private final JdbcTemplate db;private final byte[]secret;private final HttpClient http=HttpClient.newHttpClient();public WecomRobotService(JdbcTemplate d,@Value("${enterprise-risk.key-encryption-secret}")String s){db=d;secret=Arrays.copyOf(s.getBytes(StandardCharsets.UTF_8),32);}public Map<String,Object>config(){Map<String,Object>row=db.queryForMap("select enabled,webhook_ciphertext,risk_levels riskLevels,updated_by updatedBy,updated_at updatedAt from er_wecom_robot_config where id=1");String cipher=(String)row.remove("webhook_ciphertext");boolean configured=cipher!=null&&!cipher.isBlank();row.put("configured",configured);row.put("webhook",configured?decrypt(cipher):null);row.put("riskLevels",parseLevels(String.valueOf(row.get("riskLevels"))));return row;}public void save(boolean enabled,String webhook,List<String> riskLevels,String actor){if(enabled&&(webhook==null||webhook.isBlank())&&!Boolean.TRUE.equals(config().get("configured")))throw new IllegalArgumentException("启用机器人时必须填写 Webhook");String levels=String.join(",",normalizeLevels(riskLevels));if(webhook==null||webhook.isBlank())db.update("update er_wecom_robot_config set enabled=?,risk_levels=?,updated_by=?,updated_at=? where id=1",enabled,levels,actor,Instant.now());else db.update("update er_wecom_robot_config set enabled=?,webhook_ciphertext=?,risk_levels=?,updated_by=?,updated_at=? where id=1",enabled,encrypt(webhook.trim()),levels,actor,Instant.now());}private List<String> parseLevels(String raw){return Arrays.stream(raw.split(",")).map(String::trim).filter(x->Set.of("LOW","MEDIUM","HIGH","CRITICAL").contains(x)).toList();}private List<String> normalizeLevels(List<String> levels){return levels==null?List.of("CRITICAL","HIGH"):levels.stream().filter(x->Set.of("LOW","MEDIUM","HIGH","CRITICAL").contains(x)).distinct().toList();}public void test(){send("企业风控机器人测试消息");}
 public void notifyRun(long runId,String batch){Map<String,Object>cfg=config();if(!Boolean.TRUE.equals(cfg.get("enabled")))return;List<String>levels=(List<String>)cfg.get("riskLevels");if(levels==null||levels.isEmpty())return;String cond=String.join(" or ",Collections.nCopies(levels.size(),"risk_level=? or risk_level like ?"));List<Object>args=new ArrayList<>();for(String level:levels){args.add(level);args.add(level+"*%");}args.add(batch);List<Map<String,Object>>rows=db.queryForList("select risk_level level,coalesce(nullif(sales_manager,''),'未分配销售经理') manager,count(*) count from er_enterprise_profile where ("+cond+") and latest_collection_batch_no=? group by risk_level,coalesce(nullif(sales_manager,''),'未分配销售经理') order by risk_level,count(*) desc",args.toArray());if(rows.isEmpty())return;Map<String,Integer>totals=new LinkedHashMap<>();Map<String,Integer>managers=new LinkedHashMap<>();for(Map<String,Object>x:rows){String level=String.valueOf(x.get("level")).split("\\*",2)[0],manager=String.valueOf(x.get("manager"));int count=((Number)x.get("count")).intValue();totals.merge(level,count,Integer::sum);managers.merge(manager,count,Integer::sum);}int total=totals.values().stream().mapToInt(Integer::intValue).sum();StringBuilder text=new StringBuilder("企业风控采集完成\n批次号：").append(batch).append("\n风险企业：").append(total).append(" 家");for(String level:levels)if(totals.containsKey(level))text.append("\n").append(levelName(level)).append("：").append(totals.get(level)).append(" 家");text.append("\n销售经理分布：");managers.forEach((m,c)->text.append(m).append(" ").append(c).append(" 家，"));sendLogged(runId,batch,text.substring(0,text.length()-1));}private String levelName(String x){return switch(x){case "CRITICAL"->"严重风险";case "HIGH"->"高风险";case "MEDIUM"->"中风险";case "LOW"->"低风险";default->x;};}
 public List<Map<String,Object>> logs(){return db.queryForList("select id,batch_no batchNo,status,retry_count retryCount,message_text messageText,response_summary responseSummary,sent_at sentAt,created_at createdAt from er_wecom_notification_log order by id desc");}
 private void sendLogged(long run,String batch,String text){Instant now=Instant.now();db.update("insert into er_wecom_notification_log(run_id,batch_no,status,message_text,created_at) values(?,?, 'PENDING',?,?)",run,batch,text,now);Long id=db.queryForObject("select max(id) from er_wecom_notification_log",Long.class);String result="";for(int i=1;i<=3;i++)try{result=send(text);db.update("update er_wecom_notification_log set status='SUCCEEDED',retry_count=?,response_summary=?,sent_at=? where id=?",i-1,result,Instant.now(),id);return;}catch(Exception e){result=e.getMessage();}db.update("update er_wecom_notification_log set status='FAILED',retry_count=3,response_summary=? where id=?",result==null?"发送失败":result.substring(0,Math.min(1000,result.length())),id);}
 private String send(String text){Map<String,Object>c=db.queryForMap("select enabled,webhook_ciphertext from er_wecom_robot_config where id=1");if(!Boolean.TRUE.equals(c.get("enabled")))throw new IllegalStateException("企业微信机器人未启用");String url=decrypt((String)c.get("webhook_ciphertext"));String body="{\"msgtype\":\"text\",\"text\":{\"content\":\""+escape(text)+"\"}}";try{HttpResponse<String>r=http.send(HttpRequest.newBuilder(URI.create(url)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2||r.body().contains("\"errcode\":")&&!r.body().contains("\"errcode\":0"))throw new IllegalStateException("企业微信返回："+r.body());return r.body();}catch(Exception e){throw new IllegalStateException(e.getMessage(),e);}}
 private String escape(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n");}private String encrypt(String v){try{byte[]iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(secret,"AES"),new GCMParameterSpec(128,iv));return Base64.getEncoder().encodeToString(iv)+":"+Base64.getEncoder().encodeToString(c.doFinal(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private String decrypt(String v){try{String[]p=v.split(":");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(secret,"AES"),new GCMParameterSpec(128,Base64.getDecoder().decode(p[0])));return new String(c.doFinal(Base64.getDecoder().decode(p[1])),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Webhook 解密失败",e);}}
}
